package com.jagan.healthcare.controller;
import com.jagan.healthcare.dto.AppointmentRequest; import com.jagan.healthcare.model.Appointment; import com.jagan.healthcare.security.SessionAuth; import com.jagan.healthcare.service.AppointmentService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/appointments") @CrossOrigin(origins="*") public class AppointmentController {private final AppointmentService service; public AppointmentController(AppointmentService service){this.service=service;} @PostMapping public ResponseEntity<Map<String,Object>> book(@Valid @RequestBody AppointmentRequest r,HttpSession s){Appointment a=service.book(r,(String)s.getAttribute("userEmail"));return ResponseEntity.ok(Map.of("message","Appointment booked successfully.","appointment",a));} @GetMapping public List<Appointment> all(HttpSession s){SessionAuth.requireAdmin(s);return service.all();} @GetMapping("/my") public ResponseEntity<?> mine(HttpSession s){String email=SessionAuth.requireLogin(s);return ResponseEntity.ok(service.mine(email));} @DeleteMapping("/{id}") public ResponseEntity<?> cancel(@PathVariable Long id,HttpSession s){String email=SessionAuth.requireLogin(s);return ResponseEntity.ok(Map.of("message","Appointment cancelled.","appointment",service.cancel(id,email)));} }
